<?php use VazinCMS\Security; ?>
<section class="title"><div><h1>مشتریان و کاربران</h1><p><?=$total?> نتیجه</p></div></section>
<?php if($error):?><div class="alert"><?=Security::e($error)?></div><?php endif;?>
<section class="panel"><form class="filters customer-search" method="get"><input name="q" inputmode="search" value="<?=Security::e($q)?>" placeholder="شناسه عددی، نام، ایمیل، تلفن یا شرکت"><select name="status"><option value="">همه وضعیت‌ها</option><?php foreach(['active'=>'فعال','pending'=>'در انتظار','suspended'=>'تعلیق','closed'=>'بسته'] as $v=>$l):?><option value="<?=$v?>" <?=$status===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select><select name="role"><option value="">همه نقش‌ها</option><?php foreach(['client'=>'مشتری','support'=>'پشتیبان','admin'=>'مدیر','owner'=>'مالک'] as $v=>$l):?><option value="<?=$v?>" <?=$role===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select><button>جست‌وجو</button><?php if($q!==''||$status!==''||$role!=='client'):?><a class="button secondary" href="/admin/users">پاک‌کردن فیلتر</a><?php endif;?></form></section>
<section class="split"><div class="panel"><h2>کاربر جدید</h2><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><label>نام<input name="name" required></label><label>ایمیل<input type="email" name="email" required></label><label>رمز اولیه<input type="password" name="password" minlength="12" required></label><label>نقش<select name="role"><option value="client">مشتری</option><option value="support">پشتیبان</option><option value="admin">مدیر</option></select></label><button>ایجاد</button></form></div><div class="panel"><div class="table"><table><thead><tr><th>شناسه</th><th>نام</th><th>اطلاعات تماس</th><th>شرکت</th><th>نقش</th><th>وضعیت</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><code>#<?=$u['id']?></code></td><td><a href="/admin/users/<?=$u['id']?>"><?=Security::e($u['name'])?></a></td><td><div><?=Security::e($u['email'])?></div><small><?=Security::e((string)$u['phone'])?></small></td><td><?=Security::e((string)$u['company'])?></td><td><code><?=Security::e($u['role'])?></code></td><td><span class="status <?=$u['status']?>"><?=Security::e($u['status'])?></span></td></tr><?php endforeach;?></tbody></table></div><div class="pagination"><?php for($i=1;$i<=$pages;$i++):?><a class="<?=$i===$page?'active':''?>" href="?q=<?=urlencode($q)?>&status=<?=urlencode($status)?>&role=<?=urlencode($role)?>&page=<?=$i?>"><?=$i?></a><?php endfor;?></div></div></section>
